export const notificationConfig = {
    default: {
      show: false,
      title: "",
      msg: ""
    },
    approve: {
      show: true,
      title: "Approved",
      msg: `Congratulations! Carry Plan has been approved`
    },
    requestChanges: {
      show: true,
      title: "Changes Requested",
      msg: `User has been notified about requested changes`
    },

  }
